"http://www.w3.org/2000/svg\"}]}],\" \",[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"href\":\"https://www.facebook.com/vedabase\",\"className\":\"text-vb-normal-text hover:text-vb-normal-text/60\",\"alt\":\"Vedabase Facebook\",\"aria-label\":\"Vedabase Facebook\",\"children\":[\"$\",\"svg\",null,{\"stroke\":\"currentColor\",\"fill\":\"currentColor\",\"strokeWidth\":\"0\",\"viewBox\":\"0 0 512 512\",\"className\":\"inline w-8 h-8 mr-5\",\"children\":[\"$undefined\",[[\"$\",\"path\",\"0\",{\"d\":\"M504 256C504 119 393 8 256 8S8 119 8 256c0 123.78 90.69 226.38 209.25 245V327.69h-63V256h63v-54.64c0-62.15 37-96.48 93.67-96.48 27.14 0 55.52 4.84 55.52 4.84v61h-31.28c-30.8 0-40.41 19.12-40.41 38.73V256h68.78l-11 71.69h-57.78V501C413.31 482.38 504 379.78 504 256z\",\"children\":[]}]]],\"style\":{\"color\":\"$undefined\"},\"height\":\"1em\",\"width\":\"1em\",\"xmlns\":\"http://www.w3.org/2000/svg\"}]}]]}],\"His Divine Grace A.C. Bhaktivedanta Swami Prabhupāda, Founder-Ācārya of the International Society for Krishna Consciousness.\",[\"$\",\"div\",null,{\"className\":\"inline-block w-1 lg:hidden\"}],[\"$\",\"br\",null,{\"className\":\"hidden lg:block\"}],[\"Content used with permission of © The Bhaktivedanta Book Trust International, Inc. All rights reserved. And the Bhaktivedanta Archives Inc, Owner of the VedaBase™ | \",[\"$\",\"$L20\",\"privacyPolicy0\",{\"prefetch\":false,\"href\":\"/en/privacy-policy/\",\"className\":\"text-vb-normal-text/80 hover:text-vb-link underline\",\"children\":[\"Privacy policy\"]}]],[\"$\",\"div\",null,{\"className\":\"flex justify-center px-4 md:px-8 mt-6\",\"children\":[\"$\",\"a\",null,{\"href\":\"https://dashboard.simpleanalytics.com/?utm_source=vedabase.io&utm_content=badge\",\"referrerPolicy\":\"origin\",\"target\":\"_blank\",\"children\":[\"$\",\"picture\",null,{\"children\":\"$36\"}]}]}]]}]\n"])self.__next_f.push([1,"35:[\"$\",\"$L2b\",\"child-196\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Both the Pāṇḍavas and the sons of Dhṛtarāṣṭra belong to the same family, but Dhṛtarāṣṭra’s mind is disclosed herein. He deliberately claimed only his sons as Kurus, and he separated the sons of Pāṇḍu from the family heritage. One can thus understand the specific position of Dhṛtarāṣṭra in his relationship with his nephews, the sons of Pāṇḍu. As in the paddy field the unnecessary plants are taken out, so it is expected from the very beginning of these topics that in the religious field of Kurukṣetra, where the father of religion, Śrī Kṛṣṇa, was present, the unwanted plants like Dhṛtarāṣṭra’s son Duryodhana and others would be wiped out and the thoroughly religious persons, headed by Yudhiṣṭhira, would be established by the Lord. This is the significance of the words dharma-kṣetre and kuru-kṣetre, apart from their historical and Vedic importance.\"}}]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a340544a6fabf501'',t:''MTc4ODIyNDMzNA==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''head'')[0].appendChild(d)}}if(document.body){var a=document.createElement(''iframe'');a.height=1;a.width=1;a.style.position=''absolute'';a.style.top=0;a.style.left=0;a.style.border=''none'';a.style.visibility=''hidden'';document.body.appendChild(a);if(''loading''!==document.readyState)c();else if(window.addEventListener)document.addEventListener(''DOMContentLoaded'',c);else{var e=document.onreadystatechange||function(){};document.onreadystatechange=function(b){e(b);''loading''!==document.readyState&&(document.onreadystatechange=e,c())}}}})();',